import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function n(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>A self-hosted workspace to observe and intervene in bounded coding-agent attempts on GitHub issues, with mixed harnesses, visible policies and recovery controls.</p><h2 id="find-work-needing-attention" tabindex="-1">Find work needing attention <a class="header-anchor" href="#find-work-needing-attention" aria-label="Permalink to &quot;Find work needing attention&quot;">​</a></h2><p>Use <a href="/docs/features/dashboard.html">Overview</a> for complete filtered counts and automation observations. Open <a href="/docs/features/work.html">Work</a> for owners, waiting reasons and PR context; inspect <a href="/docs/features/repositories.html">Repositories</a> for intake, polling and overlaps. Factory views include mixed harnesses by default and have their own URL filters.</p><p>Finished tracking is not a measured delivery outcome. Escalation or an operator stop does not prove process termination. Unknown observations remain unknown.</p><h2 id="keep-the-actors-separate" tabindex="-1">Keep the actors separate <a class="header-anchor" href="#keep-the-actors-separate" aria-label="Permalink to &quot;Keep the actors separate&quot;">​</a></h2><p>Agents propose plans for designated Leader decisions. Operators configure policies and perform protected interventions. Human PR review and merge follow repository policy. An eligible action is an observation, not authorization; the server checks the current principal and state again.</p><h2 id="manual-work-and-native-configuration" tabindex="-1">Manual work and native configuration <a class="header-anchor" href="#manual-work-and-native-configuration" aria-label="Permalink to &quot;Manual work and native configuration&quot;">​</a></h2><p><a href="/docs/features/harnesses.html">Harnesses</a> lists implemented native pages and manual entry points. <a href="/docs/features/agent-teams.html">Teams</a>, <a href="/docs/features/agent-bridge.html">Live sessions</a> and <a href="/docs/features/agent-mail.html">Agent Mail</a> can be used without watching a repository or enabling autonomy. Native/project preferences do not select factory work. Coverage differs; see <a href="/docs/guide/multi-provider-codex-v2.html">Multi-Provider and Codex CLI</a>.</p><h2 id="current-scope" tabindex="-1">Current scope <a class="header-anchor" href="#current-scope" aria-label="Permalink to &quot;Current scope&quot;">​</a></h2><p>This reference describes the integrated product source candidate. Earlier packaged releases and separately pinned runtime or pilot environments can retain previous navigation and capabilities; integrating source does not upgrade those environments.</p><p><a href="/docs/features/harnesses.html">Harnesses</a> includes the versioned operations/readiness catalog for all five harnesses, bounded local configuration observations and guarded native pages. See the <a href="/docs/api/providers.html">Providers API</a> for the catalog contract. Native adapters remain provider-specific; catalog support does not create an editor or grant authority.</p><p>Configuration checks do not verify model access. Credential readiness remains unknown, and generic provider cards do not establish a team-slot session binding. Conditional operating support still requires the current identity, workspace and approval authority.</p><p>Feature pages describe the capabilities in the integrated source. A source update does not grant milestone or pilot acceptance. The manual Bridge trial is unperformed; pilot participants, human benefit measurements and timing comparisons are unavailable. Promotion, publication, paid execution and deployment require separate authorization.</p><p>Repository setup uses a guided, observation-only access and label check. Leader authority uses the preset&#39;s explicit <code>leader_slot_id</code>; slot order and descriptive Role text do not select it. <a href="/docs/features/repositories.html#guided-configuration">Guided configuration</a> keeps the saved configuration, the reviewed launch and the activation as separate steps.</p><h2 id="tech-stack" tabindex="-1">Tech Stack <a class="header-anchor" href="#tech-stack" aria-label="Permalink to &quot;Tech Stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Technology</th></tr></thead><tbody><tr><td>Backend</td><td>Python 3.11+ with FastAPI</td></tr><tr><td>Frontend</td><td>React 19 + TypeScript 6 + Vite 7</td></tr><tr><td>UI</td><td>shadcn/ui + Tailwind CSS</td></tr><tr><td>Charts</td><td>Recharts</td></tr><tr><td>Database</td><td>SQLite (async via SQLAlchemy + aiosqlite)</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/guide/installation.html">Installation</a></li><li><a href="/docs/guide/quick-start.html">Quick Start</a></li><li><a href="/docs/api/factory.html">Factory API</a></li><li><a href="/docs/guide/architecture.html">Architecture</a></li></ul>',19)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
